public void run()
{
    SalesTable salesTableLocal = this.salesTable();

    CustVendorBlocked blockStatus = CustTable::find(salesTableLocal.CustAccount).Blocked;
    if (blockStatus == CustVendorBlocked::METSalesinvoice)
    {
        throw warning(strFmt("@SYS18389", salesTableLocal.CustAccount, enum2Str(blockStatus)));
    }

    next run();
}
